@use '@angular/material' as mat;
@use '../vendor/mdc/theme/theme-color' as mdc-theme-color;
@use '../vendor/mdc/typography/typography' as mdc-typography;
@use '../vendor/mdc/touch-target/touch-target' as mdc-touch-target;

// The finite public bridge uses the owned16 values without forwarding an open token map.
// The public API omits unselected-pressed-icon; combined pressed states need lifecycle proof.
@function _current-color-tokens($config) {
  $color: tokens-mdc-checkbox.get-color-tokens($config);
  $base: tokens-mdc-checkbox.get-unthemable-tokens();
  @return (
    disabled-selected-icon-color: map.get($color, disabled-selected-icon-color),
    disabled-unselected-icon-color: map.get($color, disabled-unselected-icon-color),
    selected-checkmark-color: map.get($color, selected-checkmark-color),
    selected-focus-icon-color: map.get($color, selected-focus-icon-color),
    selected-hover-icon-color: map.get($color, selected-hover-icon-color),
    selected-icon-color: map.get($color, selected-icon-color),
    selected-pressed-icon-color: map.get($color, selected-pressed-icon-color),
    unselected-focus-icon-color: map.get($color, unselected-focus-icon-color),
    unselected-hover-icon-color: map.get($color, unselected-hover-icon-color),
    unselected-icon-color: map.get($color, unselected-icon-color),
    selected-focus-state-layer-color: map.get($color, selected-focus-state-layer-color),
    selected-hover-state-layer-color: map.get($color, selected-hover-state-layer-color),
    selected-pressed-state-layer-color: map.get($color, selected-pressed-state-layer-color),
    unselected-focus-state-layer-color: map.get($color, unselected-focus-state-layer-color),
    unselected-hover-state-layer-color: map.get($color, unselected-hover-state-layer-color),
    unselected-pressed-state-layer-color: map.get($color, unselected-pressed-state-layer-color),
    disabled-selected-checkmark-color: map.get($base, disabled-selected-checkmark-color),
    selected-focus-state-layer-opacity: map.get($base, selected-focus-state-layer-opacity),
    selected-hover-state-layer-opacity: map.get($base, selected-hover-state-layer-opacity),
    selected-pressed-state-layer-opacity: map.get($base, selected-pressed-state-layer-opacity),
    unselected-focus-state-layer-opacity: map.get($base, unselected-focus-state-layer-opacity),
    unselected-hover-state-layer-opacity: map.get($base, unselected-hover-state-layer-opacity),
    unselected-pressed-state-layer-opacity: map.get($base, unselected-pressed-state-layer-opacity),
    disabled-label-color: theming.get-color-from-palette(map.get($config, foreground), disabled-text),
  );
}

$label: map.get(mdc-typography.$styles, body2);
@include mat.checkbox-overrides((
  label-text-font: map.get($label, font-family),
  label-text-line-height: map.get($label, line-height),
  label-text-size: map.get($label, font-size),
  label-text-tracking: map.get($label, letter-spacing),
  label-text-weight: map.get($label, font-weight),
));

@include mat.checkbox-overrides((
  state-layer-size: map.get(tokens-mdc-checkbox.get-density-tokens($density-scale), state-layer-size),
  touch-target-size: mdc-touch-target.$height,
  touch-target-display: block,
));
@include mdc-helpers.if-touch-targets-unsupported($density-scale) {
  @include mat.checkbox-overrides((touch-target-display: none));
}

@use '@angular/material' as mat;
@use '../vendor/mdc/ripple/ripple-theme' as mdc-ripple-theme;
@use '../vendor/mdc/elevation/elevation-theme' as mdc-elevation-theme;
@use '../vendor/mdc/typography/typography' as mdc-typography;
@use '../vendor/mdc/density/density' as mdc-density;
@use '../vendor/mdc/touch-target/touch-target' as mdc-touch-target;

// These lists are finite: the four button variants accepted by the owned16 source API.
@mixin _current-ripple-color($variants, $color, $opacities) {
  $tokens: ();
  @each $variant in $variants {
    $tokens: map.merge($tokens, (
      '#{$variant}-state-layer-color': $color,
      '#{$variant}-disabled-state-layer-color': $color,
      '#{$variant}-ripple-color': rgba($color, 0.1),
      '#{$variant}-hover-state-layer-opacity': map.get($opacities, hover),
      '#{$variant}-focus-state-layer-opacity': map.get($opacities, focus),
      '#{$variant}-pressed-state-layer-opacity': map.get($opacities, press),
    ));
  }
  @include mat.button-overrides($tokens);
}

@mixin _current-ripple-theme-styles($config, $is-filled, $variants) {
  $opacities: if(map.get($config, is-dark),
    mdc-ripple-theme.$light-ink-opacities, mdc-ripple-theme.$dark-ink-opacities);
  @include _current-ripple-color($variants, mdc-theme-color.prop-value(on-surface), $opacities);
  &.mat-primary {
    @include _current-ripple-color($variants,
      mdc-theme-color.prop-value(if($is-filled, on-primary, primary)), $opacities);
  }
  &.mat-accent {
    @include _current-ripple-color($variants,
      mdc-theme-color.prop-value(if($is-filled, on-secondary, secondary)), $opacities);
  }
  &.mat-warn {
    @include _current-ripple-color($variants,
      mdc-theme-color.prop-value(if($is-filled, on-error, error)), $opacities);
  }
}

@function _current-density-tokens($height, $display) {
  $tokens: ();
  @each $variant in (text, filled, protected, outlined) {
    $tokens: map.merge($tokens, (
      '#{$variant}-container-height': $height,
      '#{$variant}-touch-target-size': mdc-touch-target.$height,
      '#{$variant}-touch-target-display': $display,
    ));
  }
  @return $tokens;
}

@include mat.button-overrides((
  protected-disabled-container-color: $disabled-container-color,
  protected-disabled-label-text-color: $disabled-ink-color,
  protected-container-color: $disabled-container-color,
  protected-label-text-color: $disabled-ink-color,
  protected-container-elevation-shadow: mdc-elevation-theme.elevation-box-shadow(0),
  protected-disabled-container-elevation-shadow: mdc-elevation-theme.elevation-box-shadow(0),
));

@include mat.button-overrides((
  outlined-disabled-label-text-color: $disabled-ink-color,
  outlined-outline-color: rgba($on-surface, 0.12),
  outlined-disabled-outline-color: rgba($on-surface, 0.12),
));

@include mat.button-overrides((
  outlined-label-text-color: $disabled-ink-color,
  outlined-disabled-label-text-color: $disabled-ink-color,
  outlined-outline-color: rgba($on-surface, 0.12),
  outlined-disabled-outline-color: rgba($on-surface, 0.12),
));

$label: map.get(mdc-typography.$styles, button);
@each $variant in (text, filled, protected, outlined) {
  @include mat.button-overrides((
    '#{$variant}-label-text-font': map.get($label, font-family),
    '#{$variant}-label-text-size': map.get($label, font-size),
    '#{$variant}-label-text-tracking': map.get($label, letter-spacing),
    '#{$variant}-label-text-weight': map.get($label, font-weight),
    '#{$variant}-label-text-transform': map.get($label, text-transform),
  ));
}

@include mat.card-overrides((
  elevated-container-color: map.get($mdc-elevated-card-color-tokens, container-color),
  elevated-container-elevation: map.get($mdc-elevated-card-color-tokens, container-elevation),
  outlined-container-color: map.get($mdc-outlined-card-color-tokens, container-color),
  outlined-container-elevation: map.get($mdc-outlined-card-color-tokens, container-elevation),
  outlined-outline-color: map.get($mdc-outlined-card-color-tokens, outline-color),
));

// Fixed owned16 geometry, emitted only by the historical full theme entry point.
@mixin _current-base() {
  $elevated: tokens-mdc-elevated-card.get-unthemable-tokens();
  $outlined: tokens-mdc-outlined-card.get-unthemable-tokens();
  .mat-mdc-card {
    @include mat.card-overrides((
      elevated-container-shape: map.get($elevated, container-shape),
      outlined-container-shape: map.get($outlined, container-shape),
      outlined-outline-width: map.get($outlined, outline-width),
    ));
  }
}
